mapper.select:
/** * selectStmtOfRsMngList : isry.couns.mngr.atrzmng.mapper.StmtOfRsMngMapper : 사유서 목록조회 */ SELECT C##RG.DEC_B64(CC.FLNM_ENCPT) AS WRTR_NM , AA.WRTR_ID AS WRTR_ID , SUBSTR(AA.WRT_YMD, 1,4)||'-'||SUBSTR(AA.WRT_YMD, 5,2)||'-'||SUBSTR(AA.WRT_YMD, 7,2) AS WRT_YMD , AA.STOFRE_TTL_NM AS STOFRE_TTL_NM , AA.APRV_STTS_SE_CD AS APRV_STTS_SE_CD , AA.STOFRE_SN AS STOFRE_SN , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'APRV_STTS_SE_CD' AND A1.CMMNS_CD_VALUE = AA.APRV_STTS_SE_CD ) AS APRV_STTS_SE_NM , COUNT(*) OVER() AS TOTAL_COUNT FROM AYC320 AA , SAA200 BB , SCA100 CC WHERE 1=1 AND AA.DEL_YN = 'N' AND AA.WRTR_ID = BB.USER_ID AND BB.ENFSN_NO = CC.ENFSN_NO(+) /* 종사자번호 */ AND CC.DEL_YN = 'N' /* 종사자 삭제여부 */
AND AA.WRTR_ID like '%'||#{userId}||'%'
AND CC.FLNM_ENCPT = C##RG.ENC_B64(#{userNm})
AND AA.APRV_STTS_SE_CD = #{aprvSttsSeCd}
AND CC.OGDP_DEPT_CD = #{deptCd}
ORDER BY AA.WRT_YMD DESC

mapper.update:
/** * updateStmtOfRsMng : isry.couns.mngr.atrzmng.mapper.StmtOfRsMngMapper : 사유서관리 상세 수정 */ UPDATE AYC320 AA /** 사이버상담 사유서 **/ SET AA.WRT_YMD = #{wrtYmd} /** 작성일자 **/ , AA.STOFRE_TTL_NM = #{stofreTtlNm} /** 사유서제목명 **/ , AA.STOFRE_CN = #{stofreCn} /** 사유서 내용 **/ , AA.APRV_STTS_SE_CD = #{aprvSttsSeCd} /** 승인상태구분코드 **/
, AA.RJCT_CS_CN = #{rjctCsCn} /** 반려사유내용 **/
, AA.ATFINO = #{atfino} /** 파일첨부번호 **/
WHERE 1=1 AND AA.STOFRE_SN = #{stofreSn}
